-- IMPORTANT SQL QUERIES

-- Current status of every container
-- JOIN + ORDER BY

SELECT
    c.name AS container,
    s.name AS service,
    cs.current_state,
    cs.restart_count
FROM container c
JOIN service s
    ON c.service_id = s.service_id
JOIN container_status cs
    ON c.container_id = cs.container_id
ORDER BY s.name;


-- Number of events generated by each container
-- JOIN + GROUP BY + COUNT

SELECT
    c.name AS container,
    COUNT(e.event_id) AS total_events
FROM container c
LEFT JOIN container_event e
    ON c.container_id = e.container_id
GROUP BY c.container_id, c.name
ORDER BY total_events DESC;


-- Containers that restarted more than 3 times
-- GROUP BY + HAVING

SELECT
    c.name AS container,
    cs.restart_count
FROM container c
JOIN container_status cs
    ON c.container_id = cs.container_id
WHERE cs.restart_count > 3
ORDER BY cs.restart_count DESC;


-- Count each type of Docker event
-- GROUP BY + aggregate function

SELECT
    event_type,
    COUNT(*) AS number_of_events
FROM container_event
GROUP BY event_type
ORDER BY number_of_events DESC;


-- Full event history for a specific container
-- JOIN + ORDER BY

SELECT
    c.name AS container,
    e.event_type,
    e.event_time
FROM container_event e
JOIN container c
    ON e.container_id = c.container_id
WHERE c.name = 'demo-api-1'
ORDER BY e.event_time DESC;


-- Containers that have experienced a failure
-- SUBQUERY

SELECT
    c.name,
    c.image
FROM container c
WHERE c.container_id IN (
    SELECT DISTINCT container_id
    FROM container_event
    WHERE event_type IN ('die', 'kill')
);


-- Services with at least one failed container
-- JOIN + GROUP BY + HAVING

SELECT
    s.name AS service,
    COUNT(DISTINCT c.container_id) AS failed_containers
FROM service s
JOIN container c
    ON s.service_id = c.service_id
JOIN container_event e
    ON c.container_id = e.container_id
WHERE e.event_type IN ('die', 'kill')
GROUP BY s.service_id, s.name
HAVING COUNT(DISTINCT c.container_id) >= 1
ORDER BY failed_containers DESC;


-- Most recent event for every container
-- SUBQUERY + JOIN

SELECT
    c.name AS container,
    e.event_type,
    e.event_time
FROM container c
JOIN container_event e
    ON c.container_id = e.container_id
WHERE e.event_time = (
    SELECT MAX(e2.event_time)
    FROM container_event e2
    WHERE e2.container_id = e.container_id
)
ORDER BY e.event_time DESC;


-- Event count per service
-- Multiple JOINs + GROUP BY

SELECT
    s.name AS service,
    COUNT(e.event_id) AS total_events
FROM service s
JOIN container c
    ON s.service_id = c.service_id
LEFT JOIN container_event e
    ON c.container_id = e.container_id
GROUP BY s.service_id, s.name
ORDER BY total_events DESC;


-- Containers with more than 2 recorded events
-- GROUP BY + HAVING

SELECT
    c.name AS container,
    COUNT(e.event_id) AS event_count
FROM container c
JOIN container_event e
    ON c.container_id = e.container_id
GROUP BY c.container_id, c.name
HAVING COUNT(e.event_id) > 2
ORDER BY event_count DESC;
